 * have paid nothing, which is the cheapest possible moment to fail.
 *
 * Never re-introduce a slice here. If a payload legitimately outgrows the cap, the
 * fix is to persist it and put a key in metadata — never to send half of it.
 */
export function packMetadata(label: string, payload: unknown): string {
  const json = JSON.stringify(payload);
  if (json.length > STRIPE_METADATA_VALUE_MAX) {
    throw new Error(
      `${label} is ${json.length} characters, over Stripe's ${STRIPE_METADATA_VALUE_MAX}-character metadata limit. ` +
        `Refusing to create a payment session rather than send a truncated payload that would take the money and ` +
        `provision nothing.`,
    );
  }
  return json;
}

/**
 * Create a Checkout session that pays for a VPS order directly (no wallet pre-fund).
 *
 * `amountCents` is the CARD leg only (the remainder after wallet credit); the FULL
 * order total rides along in metadata as `nxeonOrderPrice` so the confirm route can
 * settle the price this order was SOLD at instead of re-pricing it once the card
 * has already cleared. That re-pricing — and the silent wallet draw that paid for
 * it — is the H2 incident described on `OrderPrice` in lib/order.ts.
 *
 * `sold` lets the caller hand in the very quote it split the payment from, so the
 * card leg and the stamped total are two halves of ONE pricing. When it is omitted
 * the order is priced here, once, at the moment the session is created — still
 * before any money moves, which is the property that matters.
 */
export async function createOrderCheckout(
  user: CardUser,
  amountCents: number,
  intent: OrderIntent,
  sold?: OrderPrice | null,
  campaign?: string,
  /**
   * The managed first-month-free HOLD token, when this order was sold WITH the free
   * month. Reserved by `reserveFirstMonthFree` BEFORE this session is created, so the
   * discounted price stamped here is already backed by an exclusive hold. It rides in
   * metadata so fulfilment can CONFIRM the hold (never a fresh, contended claim) and
   * the `checkout.session.expired` webhook can RELEASE it. Null/omitted for a
   * full-price order (nothing to confirm).
   */
  promoReservationToken?: string | null,
  /**
   * The checkout-coupon HOLD token, when this order was sold WITH a coupon discount.
   * Reserved by `reserveOrderCoupon` (lib/coupon-redemption.ts) BEFORE this session is
   * created, so the discounted price stamped here is already backed by an exclusive hold
   * (per-person + a global-cap slot). It rides in metadata so fulfilment can CONFIRM the
   * hold (never a fresh, contended claim) and the `checkout.session.expired` webhook can
   * RELEASE it. Null/omitted for a full-price order.
   */
  couponReservationToken?: string | null,
): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const price = sold ?? orderPriceOf(await orderQuote(intent));
  // The card leg is a PART of the TAX-INCLUSIVE total (net + VAT); a card charge
  // larger than the whole order means the two were priced against different worlds and
  // the wallet would have to absorb a negative. Refuse to open a session rather than
  // take the money and discover it at confirm time — nothing has been charged here.
  const orderTotalCents = price.chargeCents + (price.taxCents ?? 0);
  if (orderTotalCents < amountCents) {
    throw new Error(
      `Order checkout: card leg ${amountCents}c exceeds the order total ${orderTotalCents}c`,
    );
  }
  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
  // Attach the payment to a Stripe CUSTOMER (not just an email) and record the card
  // for off-session renewal charges. `customer` and `customer_email` are mutually
  // exclusive — Stripe rejects a session carrying both — so this replaces the email.
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer: customerId,
    // Save the payment method to the customer for the unattended renewal charge the
    // billing sweep makes later — without this the card is charged once and forgotten,
    // and every card payer's first renewal fails for lack of a saved method.
    payment_intent_data: { setup_future_usage: "off_session" },
    // Bound the session's payable life so an abandoned checkout returns the customer's
    // first-month-free hold quickly (the hold's reservedUntil is pinned just past this).
    expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
          unit_amount: amountCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      nxeonOrder: packMetadata("Order intent", slim),
      // Its OWN key, not a field inside `nxeonOrder`, so the two are independently
      // sized and a long intent can never displace the price.
      nxeonOrderPrice: packMetadata("Order price", price),
      // First-month-free ad campaign tag (from the /go link cookie), carried through
      // the card round-trip so the redemption records attribution at fulfil time —
      // the webhook has no request cookies to read it from.
      nxeonPromoCampaign: sanitizeCampaign(campaign),
      // The first-month-free HOLD token. Present only when the discounted price above
      // is backed by a reserved hold; fulfilment confirms it, expiry releases it.
      ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
      // The checkout-coupon HOLD token — same lifecycle as the promo one above, for the
      // coupon's per-person + global-cap slot. Present only on a coupon-discounted order.
      ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
    },
    // Embedded: the payment form mounts in a modal on OUR page. On success Stripe
    // navigates the top window to return_url — the SAME confirm route that fulfils
    // the order, so the {CHECKOUT_SESSION_ID} round-trip is byte-for-byte unchanged.
    // No cancel_url: the modal's own close button is the cancel path (nothing charged).
    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret
    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
    : null;
}

/**
 * Create a Checkout session that pays for a GAME-server order directly (no wallet
 * pre-fund) — the game analogue of `createOrderCheckout`. `amountCents` is the CARD
 * leg only (the remainder after wallet credit); the SOLD total rides in metadata as
 * `nxeonGameOrderPrice` so fulfilment settles the price the order was SOLD at rather
 * than re-pricing it once the card has cleared (the H2 incident on lib/order.ts
 * OrderPrice). Game has no promo/coupon/VAT, so there is no reservation token to
 * carry and the price is a single scalar.
 */
export async function createGameOrderCheckout(
  user: CardUser,
  amountCents: number,
  intent: GameOrderIntent,
  sold: GameOrderPrice,
): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  // The card leg is a PART of the order total; a card charge larger than the whole
  // order means the two were priced against different worlds. Refuse to open a
  // session rather than take the money and discover it at confirm time.
  if (sold.chargeCents < amountCents) {
    throw new Error(`Game order checkout: card leg ${amountCents}c exceeds the order total ${sold.chargeCents}c`);
  }
  // Identity + money fields are small and bounded, so they are ALWAYS carried. The
  // gameplay config (which can hold a long free-text field like a Minecraft MOTD)
  // rides in its OWN key so it can never displace the price, and is DROPPED from
  // metadata if it would breach Stripe's 500-char cap: config is not money, and
  // fulfilment fills valid defaults for any field it doesn't receive (the customer
  // refines them from the server's Game settings tab after deploy). The
  // identity/price keys never drop — those are what provision + settle the order.
  const slim = {
    gamePlanId: intent.gamePlanId,
    termMonths: intent.termMonths,
    serverName: intent.serverName,
    hostname: intent.hostname,
    variant: intent.variant,
  };
  const configJson = intent.config ? JSON.stringify(intent.config) : "";
  const carryConfig = configJson !== "" && configJson.length <= 480;
  // Attach to a Stripe CUSTOMER and save the card for off-session renewals — same
  // rationale as createOrderCheckout. `customer` replaces `customer_email` (Stripe
  // forbids both on one session).
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer: customerId,
    // Record the payment method against the customer so renewals auto-charge it.
    payment_intent_data: { setup_future_usage: "off_session" },
    expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon Game Server — ${intent.hostname || intent.gamePlanId}` },
          unit_amount: amountCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      nxeonGameOrder: packMetadata("Game order intent", slim),
      // Its OWN key, independently sized, so a long intent can never displace the price.
      nxeonGameOrderPrice: packMetadata("Game order price", sold),
      ...(carryConfig ? { nxeonGameConfig: configJson } : {}),
    },
    // Embedded modal on our page; return_url is the same fulfilling confirm route.
    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret
    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
    : null;
}

/**
 * Create a Checkout session that pays for a prorated server UPGRADE directly (no
 * wallet pre-fund), applying the customer's wallet balance to the split. The CARD
 * is charged only `cardCents` (the remainder after wallet credit); the FULL
 * proration is recorded in metadata as `chargeCents` so the confirm route debits
 * the whole proration back out of the wallet. Since creditCheckoutSession credited
 * only the card portion, the wallet naturally absorbs the difference — the wallet
 * is never touched before the card clears.
 */
export async function createResizeCheckout(
  user: { id: string; email: string },
  cardCents: number,
  resize: { serverId: string; planId: string; planName?: string; prorateCents: number },
): Promise<EmbeddedCheckout | null> {

 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
 */
function parseChargeCents(raw: unknown): number | null {
  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
  return raw;
}

function parseId(raw: unknown): string | null {
  return typeof raw === "string" && raw.length > 0 ? raw : null;
}

/**
 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
 *
 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
 * not read this session" into "this session has no purchase metadata", and
 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
 * class of invisible failure that file was written to end, one layer up.
 *
 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
 * returning a lie) and classified by a pure function over its metadata.
 */
export type CheckoutPurpose =
  | {
      kind: "order";
      userId: string;
      intent: OrderIntent;
      sold: OrderPrice | null;
      campaign: string;
      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
      promoReservationToken: string | null;
      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
      couponReservationToken: string | null;
    }
  | {
      kind: "gameOrder";
      userId: string;
      intent: GameOrderIntent;
      /** The price the game order was SOLD at; null only on a malformed stamp. */
      sold: GameOrderPrice | null;
    }
  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
  | { kind: "topup"; userId: string | null }
  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
  | { kind: "unpaid" }
  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
  | { kind: "unreadable"; userId: string | null; detail: string };

/**
 * Classify a retrieved session. Pure — no clock, no network, no database — so the
 * routing decision is unit-testable and identical for the redirect and the webhook.
 */
export function classifyCheckoutSession(
  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
): CheckoutPurpose {
  const md = session.metadata ?? null;
  const userId = parseId(md?.nxeonUserId);
  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };

  const orderRaw = md?.nxeonOrder;
  if (orderRaw) {
    let intent: unknown;
    try {
      intent = JSON.parse(orderRaw);
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
    }
    if (!intent || typeof intent !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
    }
    return {
      kind: "order",
      userId,
      intent: intent as OrderIntent,
      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
      promoReservationToken: parseId(md?.nxeonPromoReservation),
      couponReservationToken: parseId(md?.nxeonCouponReservation),
    };
  }

  const gameRaw = md?.nxeonGameOrder;
  if (gameRaw) {
    let slim: Record<string, unknown>;
    try {
      slim = JSON.parse(gameRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not valid JSON" };
    }
    if (!slim || typeof slim !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not an object" };
    }
    const gamePlanId = parseId(slim.gamePlanId);
    if (!gamePlanId) {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is missing gamePlanId" };
    }
    // The gameplay config rides in its own optional key; a missing/garbled blob is
    // simply dropped (placeGameOrder fills defaults), never treated as unreadable —
    // it is not money and cannot change the settled charge.
    let config: Record<string, unknown> | null = null;
    const rawCfg = md?.nxeonGameConfig;
    if (typeof rawCfg === "string" && rawCfg !== "") {
      try {
        const p = JSON.parse(rawCfg);
        if (p && typeof p === "object") config = p as Record<string, unknown>;
      } catch {
        config = null;
      }
    }
    const intent: GameOrderIntent = {
      gamePlanId,
      termMonths: typeof slim.termMonths === "number" ? slim.termMonths : 1,
      serverName: typeof slim.serverName === "string" ? slim.serverName : undefined,
      hostname: typeof slim.hostname === "string" ? slim.hostname : undefined,
      variant: typeof slim.variant === "string" ? slim.variant : undefined,
      config,
    };
    return { kind: "gameOrder", userId, intent, sold: parseGameOrderPrice(md?.nxeonGameOrderPrice) };
  }

  const resizeRaw = md?.nxeonResize;
  if (resizeRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(resizeRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const planId = parseId(p?.planId);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || !planId || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
    }
    return { kind: "resize", userId, serverId, planId, chargeCents };
  }

  const expandRaw = md?.nxeonDiskExpand;
  if (expandRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(expandRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const addGB = parseChargeCents(p?.addGB);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || addGB === null || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
    }
    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
  }

  return { kind: "topup", userId };
}

/**
 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
 * must never be able to mistake a transport failure for "this session is a top-up".
 */
export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
  if (!stripeConfigured()) throw new Error("Stripe is not configured");
  return stripe().checkout.sessions.retrieve(sessionId);
}

/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
}

/**
 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS

 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
 * bought for its own sake.
 *
 * The wallet is the settlement bus for every card-paid purchase: the card amount
 * is credited in, then the purchase debits the full total back out. That credit is
 * plumbing, not a product, and it must not be documented as one.
 *
 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
 * against their card statement saw twice their spend. Each document was internally
 * consistent; there were simply two of them for one payment. worker/billing.ts
 * already states the rule for the renewal path: "No invoice for the card leg …
 * a second document for the card portion would double-count the same revenue."
 *
 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
 * "did this session fund a purchase" has one answer, not two.
 */
export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
  return !!(
    metadata?.nxeonOrder ||
    metadata?.nxeonGameOrder ||
    metadata?.nxeonResize ||
    metadata?.nxeonDiskExpand
  );
}

/**
 * Credit a user's wallet for a completed Checkout session, idempotently.
 * Called from both the success-redirect confirm route (works without HTTPS)
 * and the webhook (belt-and-suspenders once HTTPS is available).
 * Returns true if a credit was applied this call.
 *
 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
 * fetches it once and both the credit and the fulfilment routing read that single
 * object, so the two can never disagree about what this payment was (and a Stripe
 * read failure surfaces in one place, loudly, instead of four times as `null`).
 */
export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
  const userId = session.metadata?.nxeonUserId;
  const cents = session.amount_total ?? 0;
  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;

  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
  // session id inside the description.
  const legacy = await db.walletTransaction.findFirst({
    where: { stripeSessionId: null, description: { contains: session.id } },
  });
  if (legacy) return false;

  // Is this credit a product the customer bought, or the funding leg of something
  // else they bought? Only the first is a "Wallet top-up" and only the first gets
  // a billing document — see isPurchaseLegSession for the incident.
  const purchaseLeg = isPurchaseLegSession(session.metadata);

  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
  // read-then-write check. The confirm-redirect and the webhook can arrive
  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
  // only the database can safely decide the winner. P2002 == already credited.
  const ops: Prisma.PrismaPromise<unknown>[] = [
    db.walletTransaction.create({
      data: {
        userId,
        amountCents: cents,
        description: `Stripe payment (${session.id})`,
        stripeSessionId: session.id,
      },
    }),
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),

// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
// success-redirect route and the webhook. Plain server module (not "use server").
//
// WHY THIS EXISTS (2026-07-25)
// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
// whether `creditCheckoutSession()` returned true. That boolean is true only for
// the caller that won the race to insert the wallet credit — and the webhook
// calls the same function and discards the result. So:
//
//   * Race: the webhook's insert lands first, the confirm request gets P2002,
//     `credited === false`, and the redirect quietly lands on an empty page.
//     $249 charged, $249 credited, no server, no error, no notification.
//   * Deterministic: the customer closes the tab before `success_url` resolves,
//     so the confirm route never runs at all. Same outcome, 100% reproducible.
//
// Stripe's own guidance is explicit that a browser redirect must not be the
// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
// its own marker, not a side effect of crediting — decides the single winner.

import { db } from "./db";
import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
import { saveCardFromPaymentSession } from "./stripe-cards";
import { placeOrder } from "./order";
import { placeGameOrder } from "./game-order";
import { applyResize } from "./resize";
import { applyDiskExpand } from "./disk-expand";
import { recordDeployFunnelError } from "./deploy-funnel";
import { sendMetaConversion } from "./tracking";
import { cookies, headers } from "next/headers";

export type FulfilResult = {
  /** Where the browser should end up. The webhook ignores this. */
  redirect: string;
  /** True when THIS call performed the fulfilment work. */
  fulfilled: boolean;
  kind: "order" | "gameOrder" | "resize" | "diskExpand" | "topup" | "none";
  error?: string;
};

/**
 * Claim exclusive responsibility for fulfilling `sessionId`.
 * Returns false when another caller already holds the claim — the UNIQUE index,
 * not a read-then-write check, is what makes this safe under concurrency.
 */
async function claim(sessionId: string, kind: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
    throw e;
  }
}

async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
    .catch(() => {});
}

/**
 * Tell the customer their money is safe and someone knows. Called only on a path
 * where the card HAS cleared and fulfilment did not happen, so silence is the one
 * outcome that is never acceptable.
 */
async function notifyStalled(userId: string) {
  await db.notification
    .create({
      data: {
        userId,
        title: "Payment received — we couldn't finish setting up your server",
        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
        href: "/dashboard/billing",
      },
    })
    .catch(() => {});
}

/**
 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
 * call (this only runs where `fulfilled === true`, so no double count under the
 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
 * READ-ONLY on money: it reports the amount, it never changes a charge.
 */
async function reportPurchase(
  redirect: string,
  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
  email?: string,
  userId?: string,
  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
  prod?: string,
): Promise<string> {
  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
  const currency = (session.currency ?? "usd").toUpperCase();
  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
  // Wrapped so the webhook path (no browser request scope) simply sends without them.
  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
  try {
    const [ck, h] = await Promise.all([cookies(), headers()]);
    fbc = ck.get("_fbc")?.value || undefined;
    fbp = ck.get("_fbp")?.value || undefined;
    userAgent = h.get("user-agent") ?? undefined;
    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
  } catch {
    /* no request scope (webhook) — send without cookie/UA signals */
  }
  const { eventId } = await sendMetaConversion({
    eventName: "Purchase",
    email,
    value,
    currency,
    sourceUrl: redirect,
    fbc,
    fbp,
    userAgent,
    clientIp,
    externalId: userId,
  });
  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
}

/**
 * Credit the wallet and fulfil whatever the session was for, exactly once.
 * Safe to call repeatedly and concurrently from the redirect and the webhook.
 *
 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
 * defect found on 2026-07-27: this function used to ask three helpers for the
 * session, each of which swallowed every error into `null`, so a transient Stripe
 * failure was indistinguishable from "no purchase metadata" and fell through to
 * the top-up branch below reporting `fulfilled: true`. A real order then had its
 * card charged with no server, no FulfilledSession row and no notification — and
 * because the webhook returns 200 either way, Stripe never retried it. A throw
 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
 */
export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
  // ONE retrieve, one view of the session, shared by the credit and the routing.
  const session = await retrieveCheckoutSession(sessionId);
  const purpose = classifyCheckoutSession(session);

  // Nothing was paid (an abandoned session id, or one replayed before capture).
  // Never claim fulfilment for money that has not arrived.
  if (purpose.kind === "unpaid") {
    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
  }

  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
  // transaction). We deliberately IGNORE its return value now — it reports who
  // won the credit race, which is not the same question as "has this been
  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
  // race: the money has not reached the wallet, so nothing below may spend it.
  await creditCheckoutSession(session);

  // Purchase metadata is present but cannot be trusted. Retrying will never fix
  // it, so claim the session and record the failure exactly like a failed order:
  // reconcilable, and the customer is told. What it must NEVER become is a silent
  // wallet top-up, which is precisely what the old `null` fall-through produced.
  if (purpose.kind === "unreadable") {
    if (await claim(sessionId, "unreadable")) {
      await settle(sessionId, "FAILED", purpose.detail);
      if (purpose.userId) await notifyStalled(purpose.userId);
    }
    return {
      redirect: `${base}/dashboard/billing?paid=1`,
      fulfilled: false,
      kind: "none",
      error: purpose.detail,
    };
  }

  const order = purpose.kind === "order" ? purpose : null;
  if (order) {
    if (!(await claim(sessionId, "order"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: order.userId } });
      if (!user) throw new Error("user not found for paid order");
      // Settle the price stamped on the session BEFORE the card was charged — never
      // a fresh quote taken now. The customer has already paid the card leg of that
      // exact total; re-pricing here and taking the difference out of the wallet is
      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
      // the resize and disk-expand branches below, which have always passed the
      // amount through metadata for this reason.
      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
      // per-IP cap can't be enforced here — the per-account unique still holds, and
      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
      // the card was charged, so the double-claim race is closed regardless. Fulfilment
      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
      // fresh claim. `campaign` rides in via metadata so attribution survives the card
      // round-trip even in the webhook (no cookies).
      const serverId = await placeOrder(user, order.intent, order.sold, {
        ipHash: null,
        campaign: order.campaign,
        promoReservationToken: order.promoReservationToken,
        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
        // token rather than contending for a fresh claim — no double-claim, no over-charge.
        couponReservationToken: order.couponReservationToken,
      });
      await settle(sessionId, "DONE", serverId);
      // Record the card this order was paid with (the session set
      // setup_future_usage) so the renewal sweep can auto-charge it next cycle.
      // Guarded: the money moved and the server exists — card recording must never
      // turn a completed fulfilment into a failure.
      try {
        await saveCardFromPaymentSession(session, order.userId);
      } catch {
        /* best-effort: fulfilment already succeeded */
      }
      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
      return { redirect, fulfilled: true, kind: "order" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure
      // so it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(order.userId);
      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
      // payment-tail failure only visible server-side (the browser has left the
      // wizard, or this is the webhook). Recording it on the Payment step lets the
      // admin funnel tell "paid, then failed" from a plain abandon. Best-effort +
      // guarded so it never re-enters the money path we're unwinding.
      try {
        await recordDeployFunnelError({ product: "vps", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: order.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
    }
  }

  // Game-server order — the game analogue of the `order` branch above. Same claim /
  // settle / notify discipline; the card leg was credited to the wallet by
  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
  if (gameOrder) {
    if (!(await claim(sessionId, "gameOrder"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
      if (!user) throw new Error("user not found for paid game order");
      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
      await settle(sessionId, "DONE", serverId);
      // Save the card for off-session renewals (same guard as the order branch).
      try {
        await saveCardFromPaymentSession(session, gameOrder.userId);
      } catch {
        /* best-effort: fulfilment already succeeded */
      }
      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
      return { redirect, fulfilled: true, kind: "gameOrder" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure so
      // it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(gameOrder.userId);
      // Deploy-funnel: card cleared but the game order couldn't be placed — the same
      // server-only payment-tail failure as the VPS branch above. Best-effort + guarded.
      try {
        await recordDeployFunnelError({ product: "game", step: "Payment", stepIndex: 4, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: gameOrder.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
    }
  }

  const resize = purpose.kind === "resize" ? purpose : null;
  if (resize) {
    const back = `${base}/dashboard/servers/${resize.serverId}`;
    if (!(await claim(sessionId, "resize"))) {
      return { redirect: back, fulfilled: false, kind: "resize" };
    }
    try {
      await applyResize({
        serverId: resize.serverId,
        planId: resize.planId,
        actorUserId: resize.userId,
        chargeCents: resize.chargeCents,
      });
      await settle(sessionId, "DONE", resize.serverId);
      return { redirect: back, fulfilled: true, kind: "resize" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(resize.userId);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
    }
  }

  const expand = purpose.kind === "diskExpand" ? purpose : null;
  if (expand) {
    const back = `${base}/dashboard/servers/${expand.serverId}`;
    if (!(await claim(sessionId, "diskExpand"))) {
      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
    }
    try {
      await applyDiskExpand({
        serverId: expand.serverId,
        addGB: expand.addGB,
        actorUserId: expand.userId,
        chargeCents: expand.chargeCents,
      });
      await settle(sessionId, "DONE", expand.serverId);
      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(expand.userId);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
    }
  }

  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
  // session genuinely carried no purchase metadata — never because we failed to
  // read it (that throws) and never because we failed to parse it ("unreadable").
  //
  // The top-up session also set setup_future_usage, so record the card here too —
  // a customer who only ever tops up their wallet still ends up with a chargeable
  // card on file for renewals. Best-effort; the credit above already happened.
  if (purpose.kind === "topup" && purpose.userId) {
    try {
      await saveCardFromPaymentSession(session, purpose.userId);
    } catch {
      /* best-effort: the wallet was already credited */
    }
  }
  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
}

