410	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
411	      // A failed prior attempt: clear it so an explicit retry can proceed.
412	      if (prior?.status === "FAILED") {
413	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
414	      } else {
415	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
416	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
417	      }
418	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
419	      try {
420	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
421	      } catch {
422	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
423	      }
