/**
 * What every payment/setup flow now returns instead of a hosted Checkout URL: the
 * `client_secret` of a `ui_mode: "embedded"` Checkout Session plus the publishable
 * key, so the browser mounts Stripe Embedded Checkout in a modal on OUR page
 * (components/customer/StripeCheckoutModal) — nobody is redirected to Stripe.
 */
export type EmbeddedCheckout = { clientSecret: string; publishableKey: string };

/**
 * Embedded Checkout ui_mode + the API version that accepts it.
 *
 * WHY BOTH. The pinned stripe-node SDK (v22.3.2) sends an apiVersion that has
 * ALREADY deprecated the old `ui_mode: "embedded"` ("no longer supported, use
 * embedded_page"), while `embedded_page` itself only became valid in
 * `2026-03-25.dahlia`. So neither value works under the SDK default — we must ask
 * for `embedded_page` AND pin that version. The pin is applied PER-CALL (passed as
 * the RequestOptions arg to each `checkout.sessions.create`), NEVER on the client
 * constructor, so webhooks, retrieves and every other money call keep the SDK's
 * default version and its audited behaviour. The casts exist only because the
 * SDK's TS types predate both the enum value and the version string.
 */
export const EMBEDDED_UI_MODE = "embedded_page" as unknown as Stripe.Checkout.SessionCreateParams["ui_mode"];
export const EMBEDDED_REQUEST_OPTS = { apiVersion: "2026-03-25.dahlia" } as unknown as Stripe.RequestOptions;

/** The Stripe publishable key (safe to expose to the browser). "" when unconfigured. */
export function stripePublishableKey(): string {
  return process.env.STRIPE_PUBLISHABLE_KEY ?? "";
}

let client: Stripe | null = null;

export function stripe(): Stripe {
  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
  return client;
}

/** Stripe's hard limit on a single metadata VALUE. */
export const STRIPE_METADATA_VALUE_MAX = 500;

/**
 * How long an order Checkout session stays payable. Kept SHORT (1h) on purpose: the
 * managed first-month-free hold (lib/promo-redemption.ts reserveFirstMonthFree) lives
 * exactly as long as the session can still be paid, so a shorter session means a
 * customer who abandons checkout gets their one-time offer back sooner. Stripe's
 * accepted range is 30 min – 24 h; 1 h sits comfortably inside it.
 */
export const ORDER_CHECKOUT_EXPIRES_MS = 60 * 60 * 1000;

