import { NextRequest, NextResponse } from "next/server";
import { stripeConfigured } from "@/lib/stripe";
import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";

/**
 * Checkout success-redirect target.
 *
 * This route no longer OWNS fulfilment — it asks the shared, idempotent
 * `fulfilCheckoutSession` to do it and follows whatever redirect comes back. The
 * webhook calls the identical function, so whichever arrives first fulfils and the
 * other is a harmless no-op.
 *
 * Until 2026-07-25 the logic lived here and was gated on whether the wallet credit
 * was inserted by THIS request — which made a browser redirect the fulfilment
 * trigger. If the webhook won the race, or the customer simply closed the tab
 * before this URL resolved, the payment was captured and nothing was provisioned:
 * no server, no error, no notification. Stripe's own guidance is explicit that a
 * redirect must never be what triggers fulfilment.
 */
export async function GET(req: NextRequest) {
  const base = process.env.APP_URL ?? "";
  const sessionId = req.nextUrl.searchParams.get("session_id");
  if (!stripeConfigured() || !sessionId) {
    return NextResponse.redirect(`${base}/dashboard/billing`);
  }
  try {
    const result = await fulfilCheckoutSession(sessionId, base);
    return NextResponse.redirect(result.redirect);
  } catch {
    // Never strand the customer on an error page: the webhook is an independent
    // backstop and will fulfil this session regardless of what happened here.
    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
  }
}
