/**
 * The order intent a SHARED-HOSTING card checkout carries in its metadata — the
 * exact inputs `placeHostingOrder` needs to re-place the order at fulfilment. Small,
 * bounded fields (no SSH keys / free-text), so the whole thing fits Stripe's 500-char
 * cap comfortably. `idempotencyKey` is the wizard's per-mount token: it rides through
 * the card round-trip so the fulfilment-time `placeHostingOrder` claims the SAME
 * `hostorder:<key>` FulfilledSession the wallet path would have, and a webhook +
 * redirect can never place two accounts.
 */
export type HostOrderCheckoutIntent = {
  planId: string;
  domain?: string;
  subdomainLabel?: string;
  extraDiskGB?: number;
  termMonths?: number;
  appSlug?: string;
  idempotencyKey: string;
};

/** The order intent a BUSINESS-EMAIL card checkout carries in its metadata. */
export type EmailOrderCheckoutIntent = {
  domainName: string;
  emailPlanId: string;
  termMonths?: number;
};

/**
 * Create a Checkout session that funds a SHARED-HOSTING order by card (no wallet
 * pre-fund) — the hosting analogue of `createOrderCheckout`. `amountCents` is the
 * CARD leg only (the remainder after any wallet credit); on success
 * `fulfilCheckoutSession` credits it to the wallet and then `placeHostingOrder`
 * debits the real charge back out (its own first-month-free atomic claim decides
 * the final price at fulfilment, exactly as the wallet path does today — so the
 * card leg is never a second, drifting price). The card is saved for renewals via
 * `setup_future_usage`, which is also the renewal-method the hosting gate requires.
 */
export async function createHostingOrderCheckout(
  user: CardUser,
  amountCents: number,
  intent: HostOrderCheckoutIntent,
): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured() || amountCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  // Attach to a Stripe CUSTOMER and save the card for off-session renewals — same
  // rationale as createOrderCheckout (`customer` replaces `customer_email`, which
  // Stripe forbids alongside it).
  const { ensureStripeCustomer } = await import("./stripe-cards");
  const customerId = await ensureStripeCustomer(user);
  const label = intent.domain?.trim() || (intent.subdomainLabel?.trim() ? `${intent.subdomainLabel.trim()} subdomain` : "new site");
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer: customerId,
    payment_intent_data: { setup_future_usage: "off_session" },
    expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `Nxeon Web Hosting — ${label}` },
          unit_amount: amountCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      // The full order inputs, in their own key so the price/identity fields are
      // independently sized. packMetadata REFUSES (never truncates) if it somehow
      // outgrew the cap, which cannot silently provision nothing.
      nxeonHostOrder: packMetadata("Hosting order intent", intent),
    },
    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret
    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
    : null;
}

